// Percent-based arithmetic (× 110 ÷ 100) rather than a float rate (× 1.1):
// it keeps intermediate values integral and avoids binary floating-point
// error — 100 * 1.1 is 110.00000000000001, but (100 * 110) / 100 is exact.
const FIRST_INSURANCE_PERCENT_OF_BASE = 110;
const ADMIN_FEE = 5;

const quote = (step: QuoteStep): QuoteResult => {
  const basePremium = BASE_PREMIUMS[step.items[0].type];
  const premiumAfterFirstInsurance =
    (basePremium * FIRST_INSURANCE_PERCENT_OF_BASE) / 100;
  return { premium: premiumAfterFirstInsurance + ADMIN_FEE };
};
